// CreateCollectionV2Request Request to create a collection with schema support
//
// ## Example JSON
//
// ```json
//
//	{
//	    "name": "products",
//	    "dimension": 768,
//	    "engine": "sst",
//	    "schema": {
//	        "columns": [
//	            {"name": "category", "data_type": "text", "indexed": true},
//	            {"name": "price", "data_type": "float", "filterable": true},
//	            {"name": "description", "data_type": "text", "max_length": 10000}
//	        ],
//	        "enforcement": "hybrid",
//	        "allow_additional_fields": true
//	    },
//	    "enable_proxima_record": true
//	}
//
// ```
type CreateCollectionV2Request struct {
	// CanonicalEmbeddingPrecision Canonical embedding precision for stored vectors
	//
	// Options: "fp32" (default), "fp16", "bf16", "int8", "uint8".
	// Accepts the same string forms as the gRPC / Arrow Flight surfaces
	// (e.g. "half", "float16", "EMBEDDING_PRECISION_FP16"). The DDL
	// service applies the same normalisation, so SDKs and pgwire
	// converge on the same enum discriminant.
	CanonicalEmbeddingPrecision *string `json:"canonical_embedding_precision,omitempty"`

	// Dimension Vector dimension (required)
	Dimension int32 `json:"dimension"`

	// DistanceMetric Distance metric for vector similarity
	//
	// Options: "cosine", "euclidean", "dot_product"
	// Default: "cosine"
	DistanceMetric *string `json:"distance_metric,omitempty"`

	// EnableProximaRecord Enable ProximaRecord support for this collection
	//
	// When enabled:
	// - Records can use rich props and text_fields
	// - Schema validation is applied at insert time
	// - TEXT columns are stored in dedicated columnar format
	//
	// Default: false (backward compatible with v1)
	EnableProximaRecord *bool `json:"enable_proxima_record,omitempty"`

	// Engine Storage engine selection
	//
	// Options: "auto", "sst", "helix", "viper", "swift", "nova", "raptor", "tst"
	// Default: "auto" (system selects optimal engine)
	Engine *string `json:"engine,omitempty"`

	// IndexConfigs Index configurations (e.g. an explicit IVF or HNSW index).
	//
	// Restores v1 parity: the v1 proto create accepted `index_configs`, which
	// drive `active_algorithm_for` (e.g. an IVF index → recall-tune dispatches
	// to the IVF arm). When omitted, the engine selects a default (HNSW).
	IndexConfigs *[]IndexConfigInput `json:"index_configs,omitempty"`

	// IndexPolicy REST input for the per-collection index routing policy (mirrors proto
	// `IndexPolicy`; ADR-028).
	IndexPolicy *IndexPolicyInput `json:"index_policy,omitempty"`

	// InitialCapacity Initial capacity hint for pre-allocation
	InitialCapacity *int64 `json:"initial_capacity,omitempty"`

	// Name Collection name (required)
	Name string `json:"name"`

	// Quantization REST input for quantization config (mirrors proto `QuantizationConfig`;
	// gRPC-v2 parity with `V2QuantizationConfig`).
	Quantization *QuantizationConfigInput `json:"quantization,omitempty"`

	// Schema Schema definition for a collection
	//
	// Defines the typed columns and enforcement rules for ProximaRecord support.
	Schema *SchemaDefinition `json:"schema,omitempty"`

	// Tags Operator metadata tags, e.g. `"recall_target:0.95"`,
	// `"target_vector_count:1000"`, `"modalities:text,image"`. Consumed by the
	// recall advisor / route-health (`services/collection/recall_target.rs`).
	Tags *[]string `json:"tags,omitempty"`
}

