// RestColumnDefinition Column definition for schema
type RestColumnDefinition struct {
	// DataType Data type
	//
	// Supported types:
	// - "text": Variable-length UTF-8 text
	// - "text_large": Large text with sidecar storage
	// - "integer": 64-bit signed integer
	// - "float": 64-bit floating point
	// - "decimal": 128-bit decimal (precision, scale)
	// - "boolean": True/false
	// - "timestamp": Microseconds since epoch
	// - "timestamp_tz": Timestamp with timezone
	// - "date": Days since epoch
	// - "time": Microseconds since midnight
	// - "uuid": RFC 4122 UUID
	// - "binary": Raw bytes
	// - "json": Validated JSON
	// - "array_text", "array_integer", "array_float", "array_boolean"
	// - "map_string_string", "map_string_any"
	// - "geo_point": Latitude/longitude point
	// - "vector": Fixed-dimension vector (specify dimension)
	DataType string `json:"data_type"`

	// Filterable Enable filtering on this column
	//
	// When true, the column can be used in WHERE clauses.
	// Default: true for indexed columns, false otherwise
	Filterable *bool `json:"filterable,omitempty"`

	// Indexed Create secondary index for this column
	//
	// Improves query performance for equality/range filters.
	// Default: false
	Indexed *bool `json:"indexed,omitempty"`

	// MaxLength Maximum length for TEXT/BINARY columns
	//
	// Default: no limit
	MaxLength *int32 `json:"max_length,omitempty"`

	// Name Column name
	Name string `json:"name"`

	// Nullable Whether null values are allowed
	//
	// Default: true
	Nullable *bool `json:"nullable,omitempty"`

	// Precision Precision for DECIMAL type (1-38)
	Precision *int32 `json:"precision,omitempty"`

	// Scale Scale for DECIMAL type (0-precision)
	Scale *int32 `json:"scale,omitempty"`

	// VectorDimension Dimension for VECTOR type
	VectorDimension *int32 `json:"vector_dimension,omitempty"`
}

